// Neural 2x luma upscaler: the FSRCNNX networks chiaki-ng ships as mpv shaders, run as Metal compute
// kernels generated by Tools/gen-fsrcnnx.py. HQ has 16 feature channels, Fast has 8.
//
// Only luma goes through the network; it carries nearly all visible detail. Chroma is upsampled
// with the normal sampler when the frame is converted to RGB at 2x.

import Metal

/// A 3x3 conv + bias + PReLU layer as plain tensors: weights[tap][in][out], tap = (dy+1)*3 + (dx+1).
struct FSRCNNXConv3x3 {
    var inputs: [String]
    var outputs: [String]
    var weights: [Float]
    var bias: [Float]
    var alpha: [Float]
}

struct FSRCNNXNetwork {
    var aggregate: String
    var mapping: [FSRCNNXConv3x3] = []
    var layers: [(kernel: String, inputs: [String], outputs: [String])]
    var source: String
}

final class NeuralUpscaler {
    private let device: MTLDevice
    private let layers: [(kernel: String, inputs: [String], outputs: [String])]
    private var pipelines: [MTLComputePipelineState] = []
    private var aggregate: MTLComputePipelineState!
    private var textures: [String: MTLTexture] = [:]
    private(set) var output: MTLTexture?
    private var size = (0, 0)

    // Matrix-unit path (Metal 4): the 16-channel mapping layers, which are ~90% of the network's math,
    // run as tiled matrix multiplies on the GPU's neural accelerators over padded NHWC buffers.
    private struct MatrixLayer { var inputs: [String]; var outputs: [String]; var weights, bias, alpha: MTLBuffer }
    private var matrixLayers: [MatrixLayer] = []
    private var conv: MTLComputePipelineState?
    private var pack: MTLComputePipelineState?
    private var unpack: MTLComputePipelineState?
    private var buffers: [MTLBuffer] = []
    private static let tile = 128  // pixels per threadgroup; the frame width must be a multiple

    init?(device: MTLDevice, network: FSRCNNXNetwork) {
        self.device = device
        layers = network.layers
        do {
            let lib = try device.makeLibrary(source: network.source, options: nil)
            for layer in layers {
                pipelines.append(try device.makeComputePipelineState(function: lib.makeFunction(name: layer.kernel)!))
            }
            aggregate = try device.makeComputePipelineState(function: lib.makeFunction(name: network.aggregate)!)
        } catch {
            print("render: neural upscaler unavailable: \(error)")
            return nil
        }
        setUpMatrixPath(network.mapping)
    }

    private func setUpMatrixPath(_ mapping: [FSRCNNXConv3x3]) {
        guard #available(macOS 26.0, *), !mapping.isEmpty,
              mapping.allSatisfy({ $0.inputs.count == 4 && $0.outputs.count == 4 }) else { return }
        do {
            let opts = MTLCompileOptions()
            opts.languageVersion = .version4_0
            let lib = try device.makeLibrary(source: matrixSource, options: opts)
            conv = try device.makeComputePipelineState(function: lib.makeFunction(name: "conv3x3_16")!)
            pack = try device.makeComputePipelineState(function: lib.makeFunction(name: "pack16")!)
            unpack = try device.makeComputePipelineState(function: lib.makeFunction(name: "unpack16")!)
        } catch {
            print("render: matrix-unit path unavailable, using plain shaders (\(error))")
            return
        }
        func halves(_ v: [Float]) -> MTLBuffer {
            let h = v.map { Float16($0) }
            return device.makeBuffer(bytes: h, length: h.count * 2)!
        }
        matrixLayers = mapping.map {
            MatrixLayer(inputs: $0.inputs, outputs: $0.outputs,
                        weights: halves($0.weights), bias: halves($0.bias), alpha: halves($0.alpha))
        }
    }

    private func texture(_ w: Int, _ h: Int, _ format: MTLPixelFormat) -> MTLTexture {
        let d = MTLTextureDescriptor.texture2DDescriptor(pixelFormat: format, width: w, height: h, mipmapped: false)
        d.usage = [.shaderRead, .shaderWrite]
        d.storageMode = .private
        return device.makeTexture(descriptor: d)!
    }

    private func prepare(_ w: Int, _ h: Int) {
        guard size != (w, h) else { return }
        size = (w, h)
        textures = [:]
        for layer in layers {
            for name in layer.outputs where textures[name] == nil { textures[name] = texture(w, h, .rgba16Float) }
        }
        output = texture(w * 2, h * 2, .r16Float)
        // Two zero-bordered ping-pong buffers; only interiors are ever written, so borders stay zero.
        buffers = []
        if !matrixLayers.isEmpty, w % Self.tile == 0 {
            let length = (w + 2) * (h + 2) * 16 * 2
            for _ in 0..<2 {
                guard let b = device.makeBuffer(length: length, options: .storageModeShared) else { buffers = []; break }
                memset(b.contents(), 0, length)
                buffers.append(b)
            }
        }
    }

    /// Encodes the network on `luma` (any single-channel normalized texture). Returns the 2x luma.
    func encode(_ cb: MTLCommandBuffer, luma: MTLTexture) -> MTLTexture? {
        let w = luma.width, h = luma.height
        prepare(w, h)
        guard let out = output, let enc = cb.makeComputeCommandEncoder() else { return nil }
        textures["LUMA"] = luma
        func dispatch(_ p: MTLComputePipelineState, _ w: Int, _ h: Int) {
            enc.setComputePipelineState(p)
            let tw = p.threadExecutionWidth, th = max(1, p.maxTotalThreadsPerThreadgroup / tw / 2)
            enc.dispatchThreads(MTLSize(width: w, height: h, depth: 1),
                                threadsPerThreadgroup: MTLSize(width: tw, height: min(th, 8), depth: 1))
        }
        let matrix = buffers.count == 2 && conv != nil
        var size = SIMD2<Int32>(Int32(w), Int32(h))
        var current = 0
        var next = 0  // matrix layers replace the generated mapping layers in order (2 and 4 share names)
        for (layer, p) in zip(layers, pipelines) {
            if matrix, next < matrixLayers.count,
               matrixLayers[next].outputs == layer.outputs, matrixLayers[next].inputs == layer.inputs {
                let m = next
                next += 1
                let ml = matrixLayers[m]
                if m == 0 {  // textures -> padded buffer
                    for (i, name) in ml.inputs.enumerated() { enc.setTexture(textures[name], index: i) }
                    enc.setBuffer(buffers[current], offset: 0, index: 0)
                    enc.setBytes(&size, length: 8, index: 1)
                    dispatch(pack!, w, h)
                }
                enc.setComputePipelineState(conv!)
                enc.setBuffer(buffers[current], offset: 0, index: 0)
                enc.setBuffer(buffers[1 - current], offset: 0, index: 1)
                enc.setBuffer(ml.weights, offset: 0, index: 2)
                enc.setBuffer(ml.bias, offset: 0, index: 3)
                enc.setBuffer(ml.alpha, offset: 0, index: 4)
                enc.setBytes(&size, length: 8, index: 5)
                enc.dispatchThreadgroups(MTLSize(width: w / Self.tile, height: h, depth: 1),
                                         threadsPerThreadgroup: MTLSize(width: conv!.threadExecutionWidth, height: 1, depth: 1))
                current = 1 - current
                if m == matrixLayers.count - 1 {  // padded buffer -> textures
                    for (i, name) in ml.outputs.enumerated() { enc.setTexture(textures[name], index: i) }
                    enc.setBuffer(buffers[current], offset: 0, index: 0)
                    enc.setBytes(&size, length: 8, index: 1)
                    dispatch(unpack!, w, h)
                }
                continue
            }
            for (i, name) in layer.inputs.enumerated() { enc.setTexture(textures[name], index: i) }
            for (i, name) in layer.outputs.enumerated() { enc.setTexture(textures[name], index: layer.inputs.count + i) }
            dispatch(p, w, h)
        }
        enc.setTexture(textures[layers.last!.outputs[0]], index: 0)
        enc.setTexture(out, index: 1)
        dispatch(aggregate, w * 2, h * 2)
        enc.endEncoding()
        textures["LUMA"] = nil
        return out
    }
}

private let matrixSource = """
#include <metal_stdlib>
#include <metal_tensor>
#include <MetalPerformancePrimitives/MetalPerformancePrimitives.h>
using namespace metal;
using namespace mpp::tensor_ops;

// 3x3 conv, 16 -> 16 channels, + bias + PReLU, on zero-bordered NHWC half buffers of (W+2) x (H+2).
// Each threadgroup does 128 pixels of one row as 9 accumulated (128 x 16) * (16 x 16) matrix multiplies.
kernel void conv3x3_16(device half *inBuf [[buffer(0)]],
                       device half *outBuf [[buffer(1)]],
                       device half *wBuf [[buffer(2)]],
                       device half *bias [[buffer(3)]],
                       device half *alpha [[buffer(4)]],
                       constant int2 &size [[buffer(5)]],
                       uint2 tgid [[threadgroup_position_in_grid]])
{
    const int pw = size.x + 2;
    const int rows = pw * (size.y + 2);
    auto A = tensor<device half, dextents<int32_t, 2>, tensor_inline>(inBuf, dextents<int32_t, 2>(16, rows));
    auto B = tensor<device half, dextents<int32_t, 2>, tensor_inline>(wBuf, dextents<int32_t, 2>(16, 144));
    auto C = tensor<device half, dextents<int32_t, 2>, tensor_inline>(outBuf, dextents<int32_t, 2>(16, rows));
    constexpr auto desc = matmul2d_descriptor(128, 16, 16, false, false, true, matmul2d_descriptor::mode::multiply_accumulate);
    matmul2d<desc, execution_simdgroups<1>> op;
    const int base = (int(tgid.y) + 1) * pw + int(tgid.x) * 128 + 1;
    auto a0 = A.slice(0, base);
    auto b0 = B.slice(0, 0);
    auto acc = op.get_destination_cooperative_tensor<decltype(a0), decltype(b0), half>();
    for (uint16_t i = 0; i < acc.get_capacity(); ++i) if (acc.is_valid_element(i)) acc[i] = 0;
    #pragma unroll
    for (int t = 0; t < 9; t++) {
        auto a = A.slice(0, base + (t / 3 - 1) * pw + (t % 3 - 1));
        auto b = B.slice(0, t * 16);
        op.run(a, b, acc);
    }
    for (uint16_t i = 0; i < acc.get_capacity(); ++i) {
        if (acc.is_valid_element(i)) {
            auto idx = acc.get_multidimensional_index(i);
            half v = acc[i] + bias[idx[0]];
            acc[i] = max(v, half(0)) + alpha[idx[0]] * min(v, half(0));
        }
    }
    auto c = C.slice(0, base);
    acc.store(c);
}

kernel void pack16(texture2d<half, access::read> t0 [[texture(0)]],
                   texture2d<half, access::read> t1 [[texture(1)]],
                   texture2d<half, access::read> t2 [[texture(2)]],
                   texture2d<half, access::read> t3 [[texture(3)]],
                   device half4 *buf [[buffer(0)]],
                   constant int2 &size [[buffer(1)]],
                   uint2 gid [[thread_position_in_grid]])
{
    if (int(gid.x) >= size.x || int(gid.y) >= size.y) return;
    int i = ((int(gid.y) + 1) * (size.x + 2) + int(gid.x) + 1) * 4;
    buf[i] = t0.read(gid); buf[i + 1] = t1.read(gid); buf[i + 2] = t2.read(gid); buf[i + 3] = t3.read(gid);
}

kernel void unpack16(texture2d<half, access::write> t0 [[texture(0)]],
                     texture2d<half, access::write> t1 [[texture(1)]],
                     texture2d<half, access::write> t2 [[texture(2)]],
                     texture2d<half, access::write> t3 [[texture(3)]],
                     device half4 *buf [[buffer(0)]],
                     constant int2 &size [[buffer(1)]],
                     uint2 gid [[thread_position_in_grid]])
{
    if (int(gid.x) >= size.x || int(gid.y) >= size.y) return;
    int i = ((int(gid.y) + 1) * (size.x + 2) + int(gid.x) + 1) * 4;
    t0.write(buf[i], gid); t1.write(buf[i + 1], gid); t2.write(buf[i + 2], gid); t3.write(buf[i + 3], gid);
}
"""
